package com.semavoice.core.translation

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Compares the Kotlin tokenizer against pieces produced by the reference Python
 * `sentencepiece` package (fixtures generated by tools/gen_spm_fixtures.py).
 */
class SentencePieceTokenizerTest {
    @Serializable
    data class Case(val model: String, val text: String, val pieces: List<String>, val decoded: String)

    private fun res(path: String) = javaClass.classLoader!!.getResourceAsStream(path) ?: error("missing resource $path")
    private val json = Json { ignoreUnknownKeys = true }
    private val cases: List<Case> by lazy { json.decodeFromString(res("spm_fixtures.json").readBytes().toString(Charsets.UTF_8)) }
    private val models: Map<String, SentencePieceTokenizer> by lazy {
        mapOf(
            "m2m100" to "m2m100/sentencepiece.bpe.model",
            "opus-mul-en-source" to "opus-mul-en/source.spm",
            "opus-mul-en-target" to "opus-mul-en/target.spm",
            "opus-en-mul-source" to "opus-en-mul/source.spm",
        ).mapValues { SentencePieceTokenizer(SentencePieceModel.load(res(it.value))) }
    }

    @Test fun parsesModelMetadata() {
        val m2m = models.getValue("m2m100").model
        assertEquals(SentencePieceModel.ModelType.BPE, m2m.modelType)
        assertEquals(128_000, m2m.pieces.size)
        assertEquals("nmt_nfkc", m2m.normalizerName)
        val opus = models.getValue("opus-mul-en-source").model
        assertEquals(SentencePieceModel.ModelType.UNIGRAM, opus.modelType)
        assertEquals(32_000, opus.pieces.size)
        assertTrue(opus.addDummyPrefix)
    }

    @Test fun matchesReferenceEncodings() {
        var mismatches = 0
        val report = StringBuilder()
        for (c in cases) {
            val got = models.getValue(c.model).encodeToPieces(c.text)
            if (got != c.pieces) { mismatches++; report.append("${c.model} | ${c.text}\n  expected ${c.pieces}\n  got      $got\n") }
        }
        assertEquals("Tokenizer mismatches:\n$report", 0, mismatches)
    }

    @Test fun decodeRoundTrips() {
        for (c in cases) {
            val tok = models.getValue(c.model)
            assertEquals(c.decoded, tok.decodePieces(c.pieces))
        }
    }

    @Test fun emptyAndWhitespaceOnly() {
        val tok = models.getValue("m2m100")
        assertTrue(tok.encodeToPieces("").isEmpty())
        assertTrue(tok.encodeToPieces("   ").isEmpty())
    }
}
